select set_config('test.rule_version209',private.insert_rule_builder_version('a2090000-0000-4000-8000-000000000204','a2090000-0000-4000-8000-000000000100',replace('{"condition_ast": {"operator": "EQ", "question_version_id": "REPLACE_QUESTION_VERSION_UUID", "value": 1}, "actions": [{"type": "SCORE", "dimension": "PROCESS", "delta_basis_points": 5000}, {"type": "ANOMALY", "target": "RECIPE_PROCESS_REVIEW", "metadata": {"label_fr": "Contrôle de processus requis (recette)", "label_ar": "مراجعة العملية مطلوبة (اختبار)", "title_fr": "Contrôle de processus requis (recette)", "title_ar": "مراجعة العملية مطلوبة (اختبار)", "client_text_fr": "La réponse publiée déclenche ce contrôle de recette.", "client_text_ar": "تؤدي الإجابة إلى هذا الفحص التجريبي.", "severity": "WARNING", "blocking": false}}, {"type": "RECOMMENDATION", "target": "RECIPE_REVIEW_PROCESS", "metadata": {"label_fr": "Vérifier le processus (recette)", "label_ar": "التحقق من العملية (اختبار)", "title_fr": "Vérifier le processus (recette)", "title_ar": "التحقق من العملية (اختبار)", "client_text_fr": "Examiner le processus décrit dans la réponse.", "client_text_ar": "راجعوا العملية الموضحة في الإجابة.", "priority": 5000, "priority_basis_points": 5000, "solution_level": "GUIDANCE"}}, {"type": "OPPORTUNITY", "target": "RECIPE_PROCESS_IMPROVEMENT", "metadata": {"label_fr": "Amélioration du processus (recette)", "label_ar": "تحسين العملية (اختبار)", "title_fr": "Amélioration du processus (recette)", "title_ar": "تحسين العملية (اختبار)", "client_text_fr": "Une possibilité d’amélioration est signalée par cette règle de recette.", "client_text_ar": "تشير هذه القاعدة التجريبية إلى فرصة للتحسين.", "priority": 6000, "priority_basis_points": 6000, "solution_level": "GUIDANCE"}}, {"type": "SUGGEST_SERVICE", "target": "a2090000-0000-4000-8000-000000000107"}, {"type": "SOLUTION_LEVEL", "target": "GUIDANCE"}], "dependency_graph": {}, "priority": 10, "sensitive": false}','REPLACE_QUESTION_VERSION_UUID',current_setting('test.question_version209'))::jsonb,'Règle canonique de recette','a2090000-0000-4000-8000-000000000001',1)::text,true);
