set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a2090000-0000-4000-8000-000000000001","email":"diagnostic209-1@example.invalid","role":"authenticated","aal":"aal2"}',true);
select set_config('test.session209',(public.start_questionnaire_session('a2090000-0000-4000-8000-000000000010','a2090000-0000-4000-8000-000000000201','fr-MA',null,'canonical-start-209','a2090000-0000-4000-8000-000000000900',null)->>'session_id'),true);
select public.autosave_questionnaire_answers(current_setting('test.session209')::uuid,1,jsonb_build_array(jsonb_build_object('question_version_id',current_setting('test.question_version209'),'value',jsonb_build_object('kind','INTEGER','value','1'),'expected_answer_row_version',0)),'canonical-save-209','a2090000-0000-4000-8000-000000000901');
select set_config('test.submit209',public.submit_questionnaire_session(current_setting('test.session209')::uuid,2,'canonical-submit-209','a2090000-0000-4000-8000-000000000902')::text,true);
select is((current_setting('test.submit209')::jsonb->>'score_basis_points')::integer,5000,'real typed INTEGER answer is evaluated by the actual published SCORE rule');
select set_config('test.diagnostic209',public.complete_published_client_diagnostic_v1(current_setting('test.session209')::uuid,'a2090000-0000-4000-8000-000000000107','canonical-complete-209','a2090000-0000-4000-8000-000000000903')::text,true);
reset role;
select is((current_setting('test.diagnostic209')::jsonb->>'score')::numeric,50::numeric,'diagnostic consumes the FINAL 5000 basis-point result, not arbitrary answer.score');
select is(current_setting('test.diagnostic209')::jsonb->>'rating','IMPORTANT','existing platform health bands classify50 exactly');
select is((select count(*)::integer from public.diagnostic_anomalies where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),1,'only the actually triggered published anomaly becomes a finding');
select is((select severity from public.diagnostic_anomalies where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'WARNING','severity comes from the actual published metadata');
select is((select priority::text from public.diagnostic_recommendations where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'50.00','recommendation priority5000bps is preserved as exact50/100');
select is((select priority::text from public.diagnostic_opportunities where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'60.00','opportunity has its own published priority6000bps, not recommendation priority');
select is((select solution_level from public.diagnostic_opportunities where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'GUIDANCE','solution level comes from the explicit published action');
select ok((select d.input_manifest_hash=e.answer_manifest_hash and d.explanation->>'evaluation_id'=e.id::text and d.explanation->>'session_snapshot_hash'=snap.snapshot_hash and d.explanation->>'evaluation_reproducibility_hash'=e.reproducibility_hash and d.explanation->'triggered_actions'=e.triggered_actions from public.diagnostic_runs d join public.questionnaire_session_evaluations e on e.session_id=d.questionnaire_session_id join public.questionnaire_session_snapshots snap on snap.id=e.session_snapshot_id where d.id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'diagnostic links exact session/snapshot/evaluation/answer/action evidence');
select ok((select scoring_policy_snapshot->>'content_hash'=private.canonical_request_hash(scoring_policy_snapshot-'content_hash')and scoring_policy_snapshot->>'score_source'='FINAL_PUBLISHED_RULE_EVALUATION'from public.diagnostic_runs where id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),'canonical policy hash is DB-computed solely from the stable published comparison basis');
select is((select count(*)::integer from public.diagnostic_runs d cross join lateral jsonb_array_elements(d.scoring_policy_snapshot->'rules')r join public.question_rule_versions source on source.id=(r->>'id')::uuid where d.id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid and r->>'compiled_hash'=source.compiled_hash),1,'the actual published compiled rule hash is frozen in the policy');
set local role authenticated;
select is((public.complete_published_client_diagnostic_v1(current_setting('test.session209')::uuid,'a2090000-0000-4000-8000-000000000107','canonical-complete-209')->>'diagnostic_run_id'),current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id','same command replays the same diagnostic');
select is((public.complete_published_client_diagnostic_v1(current_setting('test.session209')::uuid,'a2090000-0000-4000-8000-000000000107','canonical-repeat-other-key-209')->>'diagnostic_run_id'),current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id','identical immutable inputs do not manufacture additional history under another key');
select throws_ok($$select public.complete_diagnostic_session(current_setting('test.session209')::uuid,'{"thresholds":{"good":1},"recommendations":{"CRITICAL":{"title_fr":"Texte client inventé"}}}','forged-policy-209')$$,'55000','CANONICAL_DIAGNOSTIC_ENDPOINT_REQUIRED','old caller-supplied policy text/thresholds can never create a diagnostic');
select throws_ok($$select public.complete_published_client_diagnostic_v1(current_setting('test.session209')::uuid,'a2090000-0000-4000-8000-000000000999','unknown-service-209')$$,'55000','PUBLISHED_DIAGNOSTIC_SERVICE_REQUIRED','selected context service must be published in the submitted questionnaire library');
select set_config('test.opportunity209',(select id::text from public.diagnostic_opportunities where diagnostic_run_id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),true);
select lives_ok($$select public.transition_diagnostic_opportunity(current_setting('test.opportunity209')::uuid,'ACCEPT',null,1,'canonical-accept-209')$$,'owner accepts the actual published opportunity');
select lives_ok($$select public.transition_diagnostic_opportunity(current_setting('test.opportunity209')::uuid,'REQUEST_RFQ',null,2,'canonical-rfq-209')$$,'only explicit owner decision makes the complete opportunity request-ready');
select set_config('test.created_request209',public.create_service_request_from_opportunity(current_setting('test.opportunity209')::uuid,'{"description":"Mission issue des règles publiées et confirmée par le Client","urgency":"NORMAL","desired_date":"","budget_minor":"125050","currency_code":"MAD","region_code":"CASABLANCA_SETTAT"}','Création canonique depuis la priorité publiée')->>'request_id',true);
select ok(current_setting('test.created_request209')is not null,'the diagnostic opportunity creates a real scoped request through the existing guarded command');
select is((public.create_service_request_from_opportunity(current_setting('test.opportunity209')::uuid,'{}','Rejeu de la demande canonique')->>'request_id'),current_setting('test.created_request209'),'conversion replays one real request without ordering twice');
select set_config('request.jwt.claims','{"sub":"a2090000-0000-4000-8000-000000000002","email":"diagnostic209-2@example.invalid","role":"authenticated","aal":"aal2"}',true);
select throws_ok($$select public.complete_published_client_diagnostic_v1(current_setting('test.session209')::uuid,'a2090000-0000-4000-8000-000000000107','foreign-complete-209')$$,'42501','DIAGNOSTIC_COMPLETE_DENIED','another actor cannot complete this organization assessment');
select is((select count(*)::integer from public.diagnostic_runs where id=(current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id')::uuid),0,'another actor cannot read the immutable diagnostic through RLS');
select throws_ok($$select public.create_service_request_from_opportunity(current_setting('test.opportunity209')::uuid,'{}','Conversion étrangère de recette')$$,'42501','OPPORTUNITY_REQUEST_SCOPE_DENIED','another actor cannot replay the conversion');
reset role;
select is((select count(*)::integer from public.audit_events where resource_id=current_setting('test.created_request209')and action='rfq.request.created'),1,'one guarded request creation audit exists');
select is((select count(*)::integer from public.audit_events where resource_id=current_setting('test.diagnostic209')::jsonb->>'diagnostic_run_id'and action='diagnostic.completed'),1,'one diagnostic creation audit exists despite repeated keys');
select ok(not has_function_privilege('authenticated','private.published_client_diagnostic_policy(uuid,uuid)','EXECUTE')and not has_function_privilege('service_role','public.complete_published_client_diagnostic_v1(uuid,uuid,text,uuid)','EXECUTE'),'no privileged or direct policy-authoring API bypass is granted');
select*from finish();
rollback;
